<script setup lang="ts">
import {ref,computed,watch,onUnmounted} from 'vue'
import {useRouter} from 'vue-router'
import {Users,Sparkles,MessageCircle,ExternalLink,Square} from 'lucide-vue-next'
import Sheet from '../components/Sheet.vue'
import {useLocal} from '../stores/local'
import {canonical,type Document,type ProgressAnchor} from '../domain/local-contract'
import type {SkillRun} from '../skills/contract'
import {stopSkillRun} from '../skills/runtime'
import {characterChunk} from './chunking'
import {progressKey} from '../writing/runtime'
import {prepareCharacterIndex,extendCharacterIndex,runCharacterIndex,stopCharacterIndex} from './index-runtime'
import type {CharacterIndex} from './index-contract'
import {characterRange,charactersAt,prepareCharacterScan,runCharacterScan,applyCharacterScan,openCharacterChat} from './runtime'
import type {CharacterScope,CharacterScan,NovelCharacter,CharacterEvidence} from './contract'
const props=defineProps<{storyId:string;branchId:string|null;anchor:ProgressAnchor|null;open:boolean}>(),emit=defineEmits<{close:[]}>(),store=useLocal(),router=useRouter()
const parent=ref<Document<CharacterIndex>|null>(null),callCap=ref(3)
const scope=ref<CharacterScope|null>(null),characters=ref<Document<NovelCharacter>[]>([]),scans=ref<Document<CharacterScan>[]>([]),active=ref<Document<CharacterScan>|null>(null),run=ref<Document<SkillRun>|null>(null),error=ref(''),busy=ref(false),opening=ref<string|null>(null),details=ref<string|null>(null),intent=ref(crypto.randomUUID())
let lifecycle=new AbortController(),epoch=0,disposed=false,poll:ReturnType<typeof setInterval>|null=null
const scopeLabel=computed(()=>scope.value?`${scope.value.sources.length} 段 · ${scope.value.sources.reduce((n,s)=>n+s.text.length,0).toLocaleString()} 字`:'已读范围')
async function load(){const vault=store.vault;if(!vault||!props.open)return;const token=++epoch;try{const anchor=props.anchor||(await vault.read<ProgressAnchor>(progressKey(props.storyId,props.branchId)))?.value;if(!anchor)throw new Error('先读一段故事，再整理人物');const chunk=await characterChunk(vault,props.storyId,props.branchId,anchor);if(!chunk)throw new Error('先读一段故事，再整理人物');const frozen=chunk.scope,rows=await charactersAt(vault,frozen),history=(await vault.list<CharacterScan>('settings')).filter(row=>row.value.assetType==='novel-character-scan'&&row.value.scope.storyId===props.storyId&&row.value.scope.branchId===props.branchId).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));if(disposed||token!==epoch||!props.open)return;scope.value=frozen;characters.value=rows;scans.value=history;if(!parent.value)parent.value=(await vault.list<CharacterIndex>('settings')).filter(r=>r.value.assetType==='novel-character-index'&&r.value.source.storyId===props.storyId&&r.value.source.branchId===props.branchId).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))[0]||null;error.value='';if(!active.value&&history[0]){active.value=history[0];run.value=await vault.read<SkillRun>(history[0].value.runId)}}catch(e){if(!disposed&&token===epoch)error.value=(e as Error).message}}
async function refresh(){const vault=store.vault;if(vault&&parent.value){const updated=await vault.read<CharacterIndex>(parent.value.id);if(!disposed&&props.open&&store.vault===vault&&vault.unlocked){parent.value=updated;const child=updated?.value.activeScanId||updated?.value.entries.at(-1)?.scanId;if(child)active.value=await vault.read<CharacterScan>(child)}}const row=active.value;if(!vault||!row||!props.open)return;const [current,scan]=await Promise.all([vault.read<SkillRun>(row.value.runId),vault.read<CharacterScan>(row.id)]);if(!disposed&&props.open&&store.vault===vault&&vault.unlocked&&active.value?.id===row.id){run.value=current;active.value=scan}}
async function start(){const vault=store.vault;if(!vault||!scope.value||busy.value)return;busy.value=true;error.value='';lifecycle.abort();lifecycle=new AbortController();const control=lifecycle,token=epoch;try{const f=scope.value,source={storyId:f.storyId,storyRevision:f.storyRevision,branchId:f.branchId,branchRevision:f.branchRevision,anchor:f.anchor},previous=parent.value;const matching=previous&&!previous.value.historical&&previous.value.authorized&&['queued','paused'].includes(previous.value.status)&&canonical(previous.value.source)===canonical(source);const row=matching?(previous.value.status==='paused'&&previous.value.activeScanId===null&&previous.value.entries.length>=previous.value.maxCalls?await extendCharacterIndex(vault,previous.id,callCap.value,intent.value,control.signal):previous):await prepareCharacterIndex(vault,source,callCap.value,intent.value,control.signal);parent.value=row;poll=setInterval(()=>void refresh(),400);await runCharacterIndex(vault,row.id,control.signal);if(disposed||!props.open||token!==epoch)return;intent.value=crypto.randomUUID();await load();await refresh()}catch(e){if(!disposed&&props.open&&token===epoch&&store.vault===vault){error.value=control.signal.aborted?'已停止，已收到的结果保留在记录中。':(e as Error).message;await refresh()}}finally{if(poll)clearInterval(poll);poll=null;busy.value=false;intent.value=crypto.randomUUID()}}
async function stop(){lifecycle.abort();if(parent.value&&store.vault)await stopCharacterIndex(store.vault,parent.value.id);if(active.value&&store.vault)await stopSkillRun(store.vault,active.value.value.runId);await refresh()}
async function chat(row:Document<NovelCharacter>){const vault=store.vault;if(!vault||!scope.value||opening.value)return;const token=epoch,control=lifecycle;opening.value=row.id;try{const id=await openCharacterChat(vault,row,scope.value.anchor,control.signal);if(disposed||token!==epoch||control.signal.aborted||!props.open||store.vault!==vault||!vault.unlocked)return;emit('close');await router.push('/local/chat/'+id)}catch(e){if(!disposed&&token===epoch&&props.open&&store.vault===vault)error.value=(e as Error).message}finally{opening.value=null}}
async function saveResult(){const vault=store.vault,row=active.value;if(!vault||!row||busy.value)return;const token=epoch,control=lifecycle;busy.value=true;error.value='';try{await applyCharacterScan(vault,row.id,control.signal);if(disposed||token!==epoch||!props.open||store.vault!==vault)return;await load();await refresh()}catch(e){if(!disposed&&token===epoch&&props.open)error.value=(e as Error).message}finally{busy.value=false}}
function sourceLink(e:CharacterEvidence){return {path:'/local/read/'+props.storyId,query:{branch:props.branchId||undefined,paragraph:e.id,offset:String(e.offset)}}}
function close(){epoch++;lifecycle.abort();if(parent.value&&busy.value&&store.vault)void stopCharacterIndex(store.vault,parent.value.id);if(active.value&&busy.value&&store.vault)void stopSkillRun(store.vault,active.value.value.runId);emit('close')}
watch(()=>props.open,open=>{if(open){lifecycle=new AbortController();active.value=null;run.value=null;parent.value=null;void load()}else{epoch++;lifecycle.abort();if(poll)clearInterval(poll)}},{immediate:true})
onUnmounted(()=>{disposed=true;epoch++;lifecycle.abort();if(parent.value&&busy.value&&store.vault)void stopCharacterIndex(store.vault,parent.value.id);if(poll)clearInterval(poll)})
</script>
<template><Sheet v-if="open" title="故事人物" @close="close"><div class="novel-people"><div class="people-toolbar"><span>已读故事</span><button v-if="busy" @click="stop"><Square :size="16"/>停止整理</button><button v-else class="final-primary" :disabled="!scope||!!opening" @click="start"><Sparkles :size="17"/>{{parent?.value.status==='paused'&&!parent.value.historical?'继续整理':characters.length?'更新人物':'整理人物'}}</button></div><div class="people-budget"><label>本次上限 <select v-model.number="callCap" aria-label="人物整理调用上限" :disabled="busy"><option :value="1">1 次</option><option :value="3">3 次</option><option :value="5">5 次</option><option :value="10">10 次</option><option :value="50">50 次</option></select></label><small v-if="parent">{{parent.value.status==='completed'?'已整理到读点':parent.value.status==='running'?'正在整理':parent.value.status==='cancelled'?'已停止':'待继续'}} · {{parent.value.completedCount}} / {{parent.value.entries.length}} <span v-if="parent.value.historical">历史记录</span></small></div><p v-if="parent?.value.error" class="final-subtle" role="status">{{parent.value.error}}</p><p v-if="error" class="final-error" role="alert">{{error}}</p><p v-if="busy" role="status">正在整理人物…</p><div v-if="!characters.length&&!busy" class="people-empty"><Users :size="36"/><p>在故事里遇见的人，都可以从这里开聊。</p></div><article v-for="row in characters" :key="row.id" class="people-card"><div class="people-title"><span class="people-avatar">{{row.value.name.slice(0,1)}}</span><div><h3>{{row.value.name}}</h3><small>{{row.value.aliases.map(a=>a.name).join(' · ')}}</small></div><button class="final-primary" :disabled="busy||!!opening" @click="chat(row)"><MessageCircle :size="16"/>开聊</button></div><p v-for="fact in row.value.facts.filter(f=>['identity','life','appearance'].includes(f.kind)).slice(0,3)" :key="canonical(fact)" class="people-fact"><span :class="['people-confidence',fact.confidence]">{{fact.confidence==='explicit'?'明确':'推测'}}</span>{{fact.text}}</p><button class="final-text-link" @click="details=details===row.id?null:row.id">{{details===row.id?'收起':'设定与原文'}}</button><div v-if="details===row.id" class="people-evidence"><div v-for="fact in row.value.facts" :key="canonical(fact)"><strong>{{fact.text}}</strong><small>{{fact.confidence==='explicit'?'原文明示':'从原文推测'}}</small><RouterLink v-for="e in fact.evidence" :key="e.id+':'+e.offset" :to="sourceLink(e)" @click="close"><ExternalLink :size="13"/>{{e.quote}}</RouterLink></div><RouterLink :to="sourceLink(row.value.primary)" @click="close">首次姓名位置 · {{row.value.primary.quote}}</RouterLink></div></article><details v-if="active&&run" class="people-history"><summary>整理记录 · {{active.value.applied?'已保存人物':run.value.status==='running'?'处理中':'未完成'}}</summary><p>{{run.value.error||active.value.error}}</p><button v-if="run.value.status==='ready'&&!active.value.applied&&!active.value.historical" :disabled="busy" @click="saveResult">保存整理结果</button><pre v-if="run.value.raw">{{run.value.raw}}</pre><RouterLink to="/local/agent/skills">查看技能与模型记录</RouterLink><small>本页不会自动重发过去的请求。</small></details><details v-if="scans.length>1"><summary>历史整理 · {{scans.length}}</summary><button v-for="scan in scans" :key="scan.id" @click="active=scan;refresh()">{{new Date(scan.value.createdAt).toLocaleString()}} · {{scan.value.applied?scan.value.characterIds.length+' 位人物':'未完成'}}</button></details></div></Sheet></template>
<style scoped>.novel-people{display:grid;gap:20px}.people-toolbar,.people-title{display:flex;align-items:center;justify-content:space-between;gap:14px}.people-budget{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;font-size:13px;color:var(--quiet)}.people-budget label{display:flex;gap:8px;align-items:center}.people-budget select{max-width:90px;min-height:40px}.people-budget small{font-size:12px}.people-toolbar>span{color:var(--quiet);font-size:13px}.people-title h3{margin:0;font:24px/1.3 var(--font-serif,serif)}.people-title>div{flex:1}.people-avatar{display:grid;place-items:center;flex:none;width:48px;height:48px;border-radius:50%;background:var(--wash);color:var(--accent);font:22px serif}.people-card{padding:22px;border:1px solid var(--edge);border-radius:16px;background:var(--paper)}.people-title small{font-size:12px;color:var(--quiet)}.people-fact{font-size:15px;line-height:1.8}.people-confidence{display:inline-flex;font-size:11px;line-height:1.5;padding:2px 7px;margin-right:9px;border-radius:5px;color:var(--accent);background:var(--wash)}.people-confidence.inferred{color:#947142;background:#94714212}.people-evidence{display:grid;gap:16px;margin-top:18px;border-top:1px solid var(--edge);padding-top:18px}.people-evidence>div{display:grid;gap:8px}.people-evidence a{display:flex;gap:7px;color:var(--accent);font-size:13px;line-height:1.6}.people-evidence small{color:var(--quiet)}.people-empty{display:grid;justify-items:center;padding:40px 12px;color:var(--quiet);text-align:center}.people-history pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:300px;overflow:auto}.people-history small{display:block;margin-top:12px;color:var(--quiet)}@media(max-width:450px){.people-card{padding:16px}.people-title{gap:10px}.people-title h3{font-size:21px}.people-title button{padding:9px 12px}}
</style>
